    "oct": {
      translationPtBr: "oct",
      exampleEn: ["After two years in hiding, Mozambique opposition leader Afonso Dhlakama arrived in Maputo on Thursday to \"ratify a pact between his Renamo party and the government ending hostilities ahead of an Oct. 15 election,\" according to reports by Reuters.", "The Halloween pet costume craze is spreading globally. Zoher Kapu is vice president of global optimization and data for eBay, the online marketplace. He told the Chicago Tribune that eBay had 1.5 million pet costumes for sale on Oct. 21 out of 800 million items listed. There were 159 million active customers in 200 countries.", "American jazz impresario George Wein turned 80 years old this month, but age isn't slowing down this globe-trotting music promoter. His pioneering series of jazz festivals, which started with private and public events in the 1950s in Newport, Rhode Island, and continue with this week's (Oct 28–30) Warsaw Jazz Festival in Poland, are credited with bringing the music festival concept to popular music. Year after year, they've also been showcasing the world's best jazz musicians, who readily praise Mr. Wein for his contributions to jazz."],
      examplePtBr: ["Após dois anos na clandestinidade, o líder da oposição moçambicana, Afonso Dhlakama, chegou a Maputo na quinta-feira para \"ratificar um pacto entre o seu partido Renamo e o governo pondo fim às hostilidades antes das eleições de 15 de Outubro\", de acordo com relatórios da Reuters.", "A moda dos disfarces do Dia das Bruxas para animais de estimação está a espalhar-se pelo mundo. Zoher Kapu é vice-presidente de otimização e dados globais do eBay, o mercado digital. Ele disse à Tribuna de Chicago que o eBay teve 1,5 milhões de fatos de animal à venda a 21 de outubro entre os 800 milhões de artigos listados. Houve 159 milhões de clientes ativos em 200 países.", "George Wein, empresário americano de jazz, fez 80 anos este mês, mas a idade não está a abrandar este promotor de música que viaja constantemente pelo mundo. A sua série pioneira de festivais de jazz, que começou com eventos privados e públicos nos anos 50 em Newport, Rhode Island, e que continua com o Festival de Jazz de Varsóvia, na Polónia, esta semana (28–30 de outubro), tem a fama de ter trazido o conceito de festival de música para a música popular. Ano após ano, os festivais têm também exibido os melhores músicos de jazz do mundo, que elogiam prontamente o sr. Wein pelas suas contribuições para o jazz."],
      context: "Tatoeba (Tradução Humana)",
    },
