      examplePtBr: ["“Todas as células vivas levam a cabo divisões celulares e a habilidade única do palbociclib de travar o processo de divisão celular (também conhecido como ‘ciclo celular’) tem, portanto, uma aplicabilidade potencialmente ampla”, disse a autora principal Amy S. Clark, MD, MSCE, professora assistente de Hematologia / Oncologia na Faculdade Perelman de Medicina e no Centro Oncológico Abramson da Universidade da Pensilvânia.", "“Todas as células vivas levam a cabo divisões celulares e a habilidade única do palbociclib de travar o processo de divisão celular (também conhecido como ‘ciclo celular’) tem, portanto, uma aplicabilidade potencialmente ampla”, disse a autora principal Amy S. Clark, MD, MSCE, professora assistente de Hematologia / Oncologia na Faculdade Perelman de Medicina e no Centro Oncológico Abramson da Universidade da Pensilvânia.", "“Todas as células vivas levam a cabo divisões celulares e a habilidade única do palbociclib de travar o processo de divisão celular (também conhecido como ‘ciclo celular’) tem, portanto, uma aplicabilidade potencialmente ampla”, disse a autora principal Amy S. Clark, MD, MSCE, professora assistente de Hematologia / Oncologia na Faculdade Perelman de Medicina e no Centro Oncológico Abramson da Universidade da Pensilvânia."],
